cd "e:/Desktop/Projects/ecomGliders" && node <<'NODE'
const fs=require('fs');
const path=require('path');
const dir='content/config/services';
const files=fs.readdirSync(dir).filter(f=>f.endsWith('.json'));

function walkImgs(obj, out=[]) {
  if (!obj || typeof obj!=='object') return out;
  if (Array.isArray(obj)) { obj.forEach(x=>walkImgs(x,out)); return out; }
  if (typeof obj.src==='string' && (obj.src.startsWith('/images/') || obj.src.startsWith('images/'))) out.push(obj.src);
  for (const k of Object.keys(obj)) walkImgs(obj[k], out);
  return out;
}

const results=[];
for (const f of files) {
  const s=JSON.parse(fs.readFileSync(path.join(dir,f),'utf8'));
  const slug=s.slug || f.replace(/\.json$/,'');
  const mods=s.modules||[];
  const modInfo={};
  for (const m of mods) {
    const t=m.type;
    if (t==='browserProof') {
      const imgs=(m.images||m.frames||[]).map(i=>i.src).filter(Boolean);
      modInfo.browserProof={count:imgs.length, srcs:imgs};
    } else if (t==='proofGallery') {
      const imgs=(m.items||[]).map(i=>i.src).filter(Boolean);
      modInfo.proofGallery={count:imgs.length, srcs:imgs};
    } else if (t==='infographicSpotlight') {
      const src=m.image?.src;
      modInfo.infographicSpotlight={count:src?1:0, srcs:src?[src]:[]};
    } else if (t==='metricChart') {
      const series=m.series||m.bars||m.rows||m.data||[];
      modInfo.metricChart={count:Array.isArray(series)?series.length:1, keys:Object.keys(m).filter(k=>!['id','type','heading','subheading'].includes(k))};
    } else if (t==='processSteps') {
      modInfo.processSteps={count:(m.steps||[]).length};
    } else if (t==='checklistMatrix') {
      modInfo.checklistMatrix={count:(m.groups||[]).length};
    } else if (t==='comparisonTable') {
      modInfo.comparisonTable={count:1};
    } else {
      modInfo[t]={count:1};
    }
  }
  const atm=s.hero?.atmosphereImage || null;
  const allSrcs=[...new Set(walkImgs(s))];
  // graphical surfaces: unique image srcs in modules+atmosphere + 1 if metricChart present
  const graphicSrcs=new Set();
  if (atm?.src) graphicSrcs.add(atm.src);
  for (const m of mods) {
    if (m.type==='infographicSpotlight' && m.image?.src) graphicSrcs.add(m.image.src);
    if (m.type==='browserProof') (m.images||[]).forEach(i=>i.src&&graphicSrcs.add(i.src));
    if (m.type==='proofGallery') (m.items||[]).forEach(i=>i.src&&graphicSrcs.add(i.src));
  }
  const hasChart=mods.some(m=>m.type==='metricChart');
  const uniqueSurfaces=graphicSrcs.size + (hasChart?1:0);
  results.push({slug, modTypes:mods.map(m=>m.type), modInfo, atmosphere:atm, allSrcs, graphicSrcs:[...graphicSrcs], uniqueSurfaces, hasChart});
}
results.sort((a,b)=>a.uniqueSurfaces-b.uniqueSurfaces);
console.log(JSON.stringify(results,null,2));
