const fs=require('fs');
const path=require('path');
const {execSync}=require('child_process');

function listFiles(dir) {
  try {
    return fs.readdirSync(dir).filter(f=>!f.startsWith('.'));
  } catch { return []; }
}

function walkFiles(dir, base='') {
  let out=[];
  try {
    for (const f of fs.readdirSync(dir,{withFileTypes:true})) {
      if (f.name.startsWith('.')) continue;
      const rel=base?`${base}/${f.name}`:f.name;
      if (f.isDirectory()) out=out.concat(walkFiles(path.join(dir,f.name), rel));
      else out.push(rel);
    }
  } catch {}
  return out;
}

const dir='content/config/services';
const files=fs.readdirSync(dir).filter(f=>f.endsWith('.json'));

// Collect ALL referenced srcs across all service JSONs
const allReferenced=new Set();
function walkSrc(obj) {
  if (!obj||typeof obj!=='object') return;
  if (Array.isArray(obj)) return obj.forEach(walkSrc);
  if (typeof obj.src==='string') allReferenced.add(obj.src);
  Object.values(obj).forEach(walkSrc);
}

const services=[];
for (const f of files) {
  const s=JSON.parse(fs.readFileSync(path.join(dir,f),'utf8'));
