  for (const m of mods) {
    if (m.type==='infographicSpotlight' && m.image?.src) graphic.add(m.image.src);
    if (m.type==='browserProof') (m.images||[]).forEach(i=>i.src&&graphic.add(i.src));
    if (m.type==='proofGallery') (m.items||[]).forEach(i=>i.src&&graphic.add(i.src));
  }
  const hasChart=mods.some(m=>m.type==='metricChart');
