  const modules={};
  for (const t of ['browserProof','metricChart','proofGallery','infographicSpotlight','processSteps','checklistMatrix','comparisonTable']) {
    const m=mods.find(x=>x.type===t);
    if (!m) { modules[t]=null; continue; }
    if (t==='browserProof') modules[t]=(m.images||[]).length+' imgs';
    else if (t==='proofGallery') modules[t]=(m.items||[]).length+' imgs';
    else if (t==='infographicSpotlight') modules[t]='1 img';
    else if (t==='metricChart') modules[t]=(m.points||[]).length+' pts';
    else if (t==='processSteps') modules[t]=(m.steps||[]).length+' steps (text)';
    else if (t==='checklistMatrix') modules[t]=(m.groups||[]).length+' groups (text)';
    else modules[t]='yes';
  }
  // Collect all srcs in this JSON
  const jsonSrcs=new Set();
  (function w(o){ if(!o||typeof o!=='object')return; if(Array.isArray(o))return o.forEach(w); if(typeof o.src==='string')jsonSrcs.add(o.src); Object.values(o).forEach(w); })(s);

  // Candidate unused assets for this slug
  const candidates=[];
  const slugDir=`public/images/services/${slug}`;
  for (const file of listFiles(slugDir)) {
    const p=`/images/services/${slug}/${file}`;
    if (![...jsonSrcs].includes(p)) candidates.push({path:p, status:'in slug folder, NOT in JSON'});
    else candidates.push({path:p, status:'USED in JSON'});
  }
  // *-service.jpg patterns
  const serviceJpg=`/images/services/${slug}-service.jpg`;
  // special mappings
